CREATE TABLE IF NOT EXISTS "conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"title" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"conversation_id" uuid NOT NULL REFERENCES "conversations"("id") ON DELETE CASCADE,"role" text NOT NULL CHECK ("role" IN ('user','assistant')),"content" text NOT NULL,"sources" jsonb DEFAULT '[]'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "messages_conversation_created_idx" ON "messages"("conversation_id","created_at");
CREATE TABLE IF NOT EXISTS "research_runs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"conversation_id" uuid REFERENCES "conversations"("id") ON DELETE SET NULL,"query" text NOT NULL,"status" text NOT NULL,"started_at" timestamptz NOT NULL DEFAULT now(),"completed_at" timestamptz);
CREATE TABLE IF NOT EXISTS "evidence" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" uuid NOT NULL REFERENCES "research_runs"("id") ON DELETE CASCADE,"url" text NOT NULL,"title" text NOT NULL,"snippet" text NOT NULL,"published_at" timestamptz,"observed_at" timestamptz NOT NULL DEFAULT now(),"content_hash" text);
CREATE INDEX IF NOT EXISTS "evidence_run_idx" ON "evidence"("run_id");
CREATE TABLE IF NOT EXISTS "memory_facts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"conversation_id" uuid REFERENCES "conversations"("id") ON DELETE SET NULL,"subject" text NOT NULL,"predicate" text NOT NULL,"object" text NOT NULL,"source_message_id" uuid,"observed_at" timestamptz NOT NULL DEFAULT now(),"metadata" jsonb DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS "memory_subject_idx" ON "memory_facts"("subject");
